import 'package:buildflow/features/chat/domain/entities/chat_enums.dart';
import 'package:buildflow/features/chat/domain/entities/message_attachment.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'message.freezed.dart';
part 'message.g.dart';

@freezed
abstract class Message with _$Message {
  const factory Message({
    required String id,

    /// Generated by the sending client (uuid). Sending again with the same
    /// clientId returns the message instead of creating a duplicate.
    required String clientId,
    required String chatId,
    required String senderId,
    required MessageKind kind,
    required DateTime createdAt,

    /// Delivery state as the current user sees it; meaningful for their
    /// own messages only.
    @Default(MessageStatus.sent) MessageStatus status,
    String? text,
    @Default([]) List<MessageAttachment> attachments,

    /// Whether the current user has played this voice note; others' notes
    /// show a dot until then.
    @Default(false) bool listened,

    /// The report of a [MessageKind.report] message.
    String? reportId,

    /// What a [MessageKind.system] message reports, and about whom.
    ChatSystemEvent? systemEvent,
    String? subjectUserId,
  }) = _Message;

  factory Message.fromJson(Map<String, dynamic> json) =>
      _$MessageFromJson(json);
}
